//! End-to-end flows through the core facade: commands in, events out.
//! Audio is rendered to WAV files or discarded; no sound card is needed.
//! All audio, images and lyrics are generated by the tests.

use std::f32::consts::TAU;
use std::path::{Path, PathBuf};
use std::time::{Duration, Instant};

use crossbeam_channel::Receiver;
use jf_core::{
    Collection, Command, Config, Core, CrossfadeSettings, Event, HueSource, OutputKind, RepeatMode,
    ScanStatus, Status, TrackQuery, TrackRef, TrackRow, TrackSort,
};

const RATE: u32 = 44_100;

fn sine_wav(path: &Path, freq: f32, seconds: f32) {
    let spec = hound::WavSpec {
        channels: 2,
        sample_rate: RATE,
        bits_per_sample: 16,
        sample_format: hound::SampleFormat::Int,
    };
    let mut w = hound::WavWriter::create(path, spec).unwrap();
    let frames = (RATE as f32 * seconds) as u32;
    for i in 0..frames {
        let v = ((TAU * freq * i as f32 / RATE as f32).sin() * 0.25 * f32::from(i16::MAX)) as i16;
        w.write_sample(v).unwrap();
        w.write_sample(v).unwrap();
    }
    w.finalize().unwrap();
}

fn config(dir: &Path, output: OutputKind, persist: bool) -> Config {
    let mut c = Config::new(dir.join("data"), dir.join("cache"));
    c.output = output;
    c.persist_session = persist;
    c.restore_session = persist;
    c
}

/// Collects events until `done` returns true or the timeout passes.
fn wait_for(
    rx: &crossbeam_channel::Receiver<Event>,
    timeout: Duration,
    mut done: impl FnMut(&Event) -> bool,
) -> Vec<Event> {
    let end = Instant::now() + timeout;
    let mut seen = Vec::new();
    while let Some(left) = end.checked_duration_since(Instant::now()) {
        match rx.recv_timeout(left) {
            Ok(ev) => {
                let stop = done(&ev);
                seen.push(ev);
                if stop {
                    return seen;
                }
            }
            Err(_) => break,
        }
    }
    panic!("timed out; events seen: {seen:#?}");
}

fn files(dir: &Path, names: &[(&str, f32)], seconds: f32) -> Vec<PathBuf> {
    names
        .iter()
        .map(|(name, freq)| {
            let p = dir.join(name);
            sine_wav(&p, *freq, seconds);
            p
        })
        .collect()
}

fn now_playing_titles(events: &[Event]) -> Vec<String> {
    events
        .iter()
        .filter_map(|e| match e {
            Event::NowPlaying(Some(np)) => Some(np.title.clone()),
            _ => None,
        })
        .collect()
}

#[test]
fn plays_a_queue_to_the_end_into_a_wav_file() {
    let dir = tempfile::tempdir().unwrap();
    let music = files(
        dir.path(),
        &[("a.wav", 440.0), ("b.wav", 660.0), ("c.wav", 880.0)],
        0.5,
    );
    let out = dir.path().join("out.wav");
    let core = Core::start(config(
        dir.path(),
        OutputKind::WavFile {
            path: out.clone(),
            realtime: false,
        },
        false,
    ))
    .unwrap();
    let rx = core.subscribe();
    core.send(Command::PlayTracks {
        tracks: music.iter().cloned().map(TrackRef::File).collect(),
        start: 0,
    });
    let events = wait_for(
        &rx,
        Duration::from_secs(20),
        |e| matches!(e, Event::Playback(p) if p.status == Status::Ended),
    );
    assert_eq!(now_playing_titles(&events), vec!["a", "b", "c"]);
    assert_eq!(core.snapshot().playback.status, Status::Ended);
    core.shutdown();

    let reader = hound::WavReader::open(&out).unwrap();
    let seconds = reader.duration() as f32 / reader.spec().sample_rate as f32;
    assert!(
        (seconds - 1.5).abs() < 0.08,
        "rendered {seconds} s, expected 1.5 s"
    );
}

#[test]
fn lyrics_and_theme_follow_the_current_track() {
    let dir = tempfile::tempdir().unwrap();
    let album = dir.path().join("album");
    std::fs::create_dir_all(&album).unwrap();
    let music = files(&album, &[("01 Tone.wav", 440.0)], 0.4);
    // Original test lines, not from any song.
    std::fs::write(
        album.join("01 Tone.lrc"),
        "[00:00.10]First test line\n[00:00.30]Second test line\n",
    )
    .unwrap();
    image::RgbImage::from_pixel(32, 32, image::Rgb([200, 30, 40]))
        .save(album.join("cover.png"))
        .unwrap();

    let core = Core::start(config(dir.path(), OutputKind::Null { realtime: true }, false)).unwrap();
    let rx = core.subscribe();
    core.send(Command::PlayTracks {
        tracks: vec![TrackRef::File(music[0].clone())],
        start: 0,
    });
    let mut lyrics = None;
    let mut theme = None;
    wait_for(&rx, Duration::from_secs(20), |e| {
        match e {
            Event::Lyrics(l) => lyrics = Some(l.clone()),
            Event::Theme(t) => theme = Some(t.clone()),
            _ => {}
        }
        lyrics.is_some() && theme.is_some()
    });
    let lyrics = lyrics.unwrap();
    let doc = lyrics.doc.as_ref().expect("sidecar lyrics");
    assert_eq!(doc.lines.len(), 2);
    assert!(lyrics.timeline.is_some());
    let theme = theme.unwrap();
    assert!(theme.from_artwork, "a saturated red cover gives an artwork hue");
    assert!(
        theme.hue < 45.0 || theme.hue > 330.0,
        "red hue, got {}",
        theme.hue
    );
    assert!(theme.backdrop_light.as_ref().is_some_and(|p| p.is_file()));
    assert!(theme.backdrop_dark.as_ref().is_some_and(|p| p.is_file()));
}

#[test]
fn next_previous_and_jump() {
    let dir = tempfile::tempdir().unwrap();
    let music = files(
        dir.path(),
        &[("one.wav", 440.0), ("two.wav", 550.0), ("three.wav", 660.0)],
        5.0,
    );
    let core = Core::start(config(dir.path(), OutputKind::Null { realtime: true }, false)).unwrap();
    let rx = core.subscribe();
    core.send(Command::PlayTracks {
        tracks: music.iter().cloned().map(TrackRef::File).collect(),
        start: 0,
    });
    let is_now =
        |title: &'static str| move |e: &Event| matches!(e, Event::NowPlaying(Some(np)) if np.title == title);
    wait_for(&rx, Duration::from_secs(10), is_now("one"));
    core.send(Command::Next);
    wait_for(&rx, Duration::from_secs(10), is_now("two"));
    core.send(Command::Previous);
    wait_for(&rx, Duration::from_secs(10), is_now("one"));
    let third = core.queue_window(0, 10)[2].uid;
    core.send(Command::JumpTo { uid: third });
    wait_for(&rx, Duration::from_secs(10), is_now("three"));
    core.send(Command::Pause);
    wait_for(
        &rx,
        Duration::from_secs(10),
        |e| matches!(e, Event::Playback(p) if p.status == Status::Paused),
    );
    assert_eq!(core.snapshot().queue.position, Some(2));
}

#[test]
fn repeat_one_replays_the_current_track() {
    let dir = tempfile::tempdir().unwrap();
    let music = files(dir.path(), &[("loop.wav", 440.0), ("after.wav", 880.0)], 0.3);
    let core = Core::start(config(dir.path(), OutputKind::Null { realtime: true }, false)).unwrap();
    let rx = core.subscribe();
    core.send(Command::SetRepeat {
        mode: RepeatMode::One,
    });
    core.send(Command::PlayTracks {
        tracks: music.iter().cloned().map(TrackRef::File).collect(),
        start: 0,
    });
    let mut starts = 0;
    let events = wait_for(&rx, Duration::from_secs(20), |e| {
        if matches!(e, Event::Queue(_)) {
            starts = core_history_len(&core);
        }
        starts >= 3
    });
    assert!(
        now_playing_titles(&events).iter().all(|t| t == "loop"),
        "{:?}",
        now_playing_titles(&events)
    );
}

fn core_history_len(core: &Core) -> usize {
    core.history().len()
}

#[test]
fn the_session_survives_a_restart() {
    let dir = tempfile::tempdir().unwrap();
    let music = files(dir.path(), &[("x.wav", 440.0), ("y.wav", 550.0)], 5.0);
    let (current, len) = {
        let core = Core::start(config(dir.path(), OutputKind::Null { realtime: true }, true)).unwrap();
        let rx = core.subscribe();
        core.send(Command::SetRepeat {
            mode: RepeatMode::All,
        });
        core.send(Command::PlayTracks {
            tracks: music.iter().cloned().map(TrackRef::File).collect(),
            start: 1,
        });
        wait_for(
            &rx,
            Duration::from_secs(10),
            |e| matches!(e, Event::NowPlaying(Some(np)) if np.title == "y"),
        );
        let snap = core.snapshot().queue;
        core.shutdown();
        (snap.current.unwrap().uid, snap.len)
    };
    let core = Core::start(config(dir.path(), OutputKind::Null { realtime: true }, true)).unwrap();
    let snap = core.snapshot().queue;
    assert_eq!(snap.len, len);
    assert_eq!(snap.current.map(|c| c.uid), Some(current));
    assert_eq!(snap.repeat, RepeatMode::All);
    assert_eq!(
        core.snapshot().playback.status,
        Status::Stopped,
        "restores paused, never auto-plays"
    );
}

#[test]
fn scan_search_and_play_from_the_library() {
    let dir = tempfile::tempdir().unwrap();
    let music = dir.path().join("music");
    std::fs::create_dir_all(&music).unwrap();
    files(
        &music,
        &[("Moonlit Harbor.wav", 440.0), ("Paper Lanterns.wav", 550.0)],
        0.3,
    );
    let out = dir.path().join("out.wav");
    let core = Core::start(config(
        dir.path(),
        OutputKind::WavFile {
            path: out,
            realtime: false,
        },
        false,
    ))
    .unwrap();
    let rx = core.subscribe();
    core.send(Command::AddRoot { path: music.clone() });
    core.send(Command::Rescan);
    let events = wait_for(&rx, Duration::from_secs(30), |e| {
        matches!(e, Event::Scan(ScanStatus::Finished(_)))
    });
    let Some(Event::Scan(ScanStatus::Finished(report))) = events.last() else {
        unreachable!()
    };
    assert_eq!(report.added, 2, "{report:?}");
    assert_eq!(core.roots().unwrap(), vec![std::path::absolute(&music).unwrap()]);

    let tracks = core.tracks_for_query("harbor", 10).unwrap();
    assert_eq!(tracks.len(), 1);
    core.send(Command::PlayTracks { tracks, start: 0 });
    let events = wait_for(
        &rx,
        Duration::from_secs(20),
        |e| matches!(e, Event::Playback(p) if p.status == Status::Ended),
    );
    assert_eq!(now_playing_titles(&events), vec!["Moonlit Harbor"]);
}

#[test]
fn bad_entries_are_skipped_with_an_error() {
    let dir = tempfile::tempdir().unwrap();
    let good = files(dir.path(), &[("good.wav", 440.0)], 0.3);
    let corrupt = dir.path().join("corrupt.flac");
    std::fs::write(&corrupt, b"this is not audio").unwrap();
    let missing = dir.path().join("missing.wav");
    let out = dir.path().join("out.wav");
    let core = Core::start(config(
        dir.path(),
        OutputKind::WavFile {
            path: out,
            realtime: false,
        },
        false,
    ))
    .unwrap();
    let rx = core.subscribe();
    core.send(Command::PlayTracks {
        tracks: vec![
            TrackRef::File(missing),
            TrackRef::File(corrupt),
            TrackRef::File(good[0].clone()),
        ],
        start: 0,
    });
    let events = wait_for(
        &rx,
        Duration::from_secs(20),
        |e| matches!(e, Event::Playback(p) if p.status == Status::Ended),
    );
    assert_eq!(now_playing_titles(&events), vec!["good"]);
    let errors = events.iter().filter(|e| matches!(e, Event::Error { .. })).count();
    assert!(errors >= 2, "one error per skipped entry: {events:#?}");
}

// ---- playlists, favourites, play statistics, folder watching ---------------

/// A core over a scanned library of generated tracks; every library message
/// of the scan has arrived when it returns.
fn library_core(
    dir: &Path,
    names: &[(&str, f32)],
    seconds: f32,
    realtime: bool,
) -> (Core, Receiver<Event>, PathBuf) {
    let music = dir.join("music");
    std::fs::create_dir_all(&music).unwrap();
    files(&music, names, seconds);
    let core = Core::start(config(
        dir,
        OutputKind::WavFile {
            path: dir.join("out.wav"),
            realtime,
        },
        false,
    ))
    .unwrap();
    let rx = core.subscribe();
    core.send(Command::AddRoot { path: music.clone() });
    let mut finished = false;
    wait_for(&rx, Duration::from_secs(30), |e| {
        if let Event::Scan(ScanStatus::Finished(report)) = e {
            assert_eq!(
                report.added as usize,
                names.len(),
                "AddRoot scans the folder: {report:?}"
            );
            finished = true;
        }
        finished && matches!(e, Event::LibraryChanged { .. })
    });
    (core, rx, music)
}

/// Sends a library edit and waits until it is applied.
fn edit(core: &Core, rx: &Receiver<Event>, command: Command) {
    let before = core.snapshot().library_revision;
    let id = core.send(command);
    wait_for(rx, Duration::from_secs(10), |e| match e {
        Event::CommandFailed { id: failed, error } if *failed == id => panic!("{error}"),
        Event::LibraryChanged { revision } => *revision > before,
        _ => false,
    });
}

fn library_ids(core: &Core) -> Vec<(String, i64)> {
    core.tracks(&TrackQuery {
        sort: TrackSort::Title,
        ..TrackQuery::default()
    })
    .unwrap()
    .into_iter()
    .map(|t| (t.title, t.id))
    .collect()
}

fn titles(rows: &[TrackRow]) -> Vec<&str> {
    rows.iter().map(|r| r.title.as_str()).collect()
}

#[test]
fn playlists_are_edited_exported_imported_and_played() {
    let dir = tempfile::tempdir().unwrap();
    let (core, rx, _) = library_core(
        dir.path(),
        &[("a.wav", 440.0), ("b.wav", 550.0), ("c.wav", 660.0)],
        0.2,
        false,
    );
    let ids: Vec<i64> = library_ids(&core).into_iter().map(|(_, id)| id).collect();
    let loose = files(dir.path(), &[("loose.wav", 330.0)], 0.2).remove(0);

    let request = core.send(Command::CreatePlaylist {
        name: "Mix".into(),
        tracks: vec![TrackRef::Library(ids[2]), TrackRef::Library(ids[0])],
    });
    let events = wait_for(
        &rx,
        Duration::from_secs(10),
        |e| matches!(e, Event::PlaylistCreated { request: r, .. } if *r == request),
    );
    let Some(Event::PlaylistCreated { id, .. }) = events.last() else {
        unreachable!()
    };
    let id = *id;
    edit(
        &core,
        &rx,
        Command::AddToPlaylist {
            id,
            tracks: vec![TrackRef::File(loose.clone())],
        },
    );
    let entries = core.playlist_entries(id, 0, 100).unwrap();
    let rows: Vec<TrackRow> = entries.iter().map(|e| e.row.clone()).collect();
    assert_eq!(titles(&rows), ["c", "a", "loose"]);
    assert_eq!(
        rows[2].track,
        TrackRef::File(loose.clone()),
        "not in the catalogue"
    );
    assert!(rows.iter().all(|r| !r.missing && !r.favorite));
    assert!(rows[0].duration_ms.is_some());

    edit(
        &core,
        &rx,
        Command::MovePlaylistEntry {
            id,
            entry: entries[1].entry_id,
            to: 0,
        },
    );
    edit(
        &core,
        &rx,
        Command::RemoveFromPlaylist {
            id,
            entries: vec![entries[0].entry_id],
        },
    );
    edit(
        &core,
        &rx,
        Command::RenamePlaylist {
            id,
            name: "Evening".into(),
        },
    );
    let lists = core.playlists().unwrap();
    assert_eq!(lists.len(), 1);
    assert_eq!((lists[0].name.as_str(), lists[0].entry_count), ("Evening", 2));
    let rows: Vec<TrackRow> = core
        .playlist_entries(id, 0, 100)
        .unwrap()
        .into_iter()
        .map(|e| e.row)
        .collect();
    assert_eq!(titles(&rows), ["a", "loose"]);

    // Export, then import the file back as a second playlist.
    let m3u = dir.path().join("Evening copy.m3u8");
    core.export_playlist(id, &m3u).unwrap();
    let import = core.send(Command::ImportPlaylist { path: m3u.clone() });
    let events = wait_for(&rx, Duration::from_secs(10), |e| match e {
        Event::CommandFailed { id: failed, error } if *failed == import => panic!("{error}"),
        Event::PlaylistCreated { request, .. } => *request == import,
        _ => false,
    });
    let Some(Event::PlaylistCreated { id: copy, .. }) = events.last() else {
        unreachable!()
    };
    let copy = core.playlist(*copy).unwrap().expect("the imported playlist");
    assert_eq!((copy.name.as_str(), copy.entry_count), ("Evening copy", 2));

    // A file that went missing is left out; `start` names the playlist entry.
    std::fs::remove_file(&loose).unwrap();
    let rows: Vec<TrackRow> = core
        .playlist_entries(id, 0, 100)
        .unwrap()
        .into_iter()
        .map(|e| e.row)
        .collect();
    assert!(rows[1].missing, "{rows:?}");
    edit(
        &core,
        &rx,
        Command::AddToPlaylist {
            id,
            tracks: vec![TrackRef::Library(ids[1])],
        },
    );
    core.send(Command::PlayCollection {
        collection: Collection::Playlist { id },
        start: 1,
        shuffle: false,
    });
    let events = wait_for(
        &rx,
        Duration::from_secs(20),
        |e| matches!(e, Event::Playback(p) if p.status == Status::Ended),
    );
    assert_eq!(
        now_playing_titles(&events),
        vec!["b"],
        "starts after the missing entry"
    );
    assert_eq!(core.snapshot().queue.len, 2, "a and b, without the missing file");

    edit(&core, &rx, Command::DeletePlaylist { id });
    assert_eq!(core.playlists().unwrap().len(), 1);
    let id = core.send(Command::PlayCollection {
        collection: Collection::Playlist { id },
        start: 0,
        shuffle: false,
    });
    wait_for(
        &rx,
        Duration::from_secs(10),
        |e| matches!(e, Event::CommandFailed { id: failed, .. } if *failed == id),
    );
}

#[test]
fn favourites_play_and_finished_plays_count() {
    let dir = tempfile::tempdir().unwrap();
    let (core, rx, _) = library_core(dir.path(), &[("a.wav", 440.0), ("b.wav", 550.0)], 0.2, false);
    let ids: Vec<i64> = library_ids(&core).into_iter().map(|(_, id)| id).collect();
    edit(
        &core,
        &rx,
        Command::SetFavorite {
            track: TrackRef::Library(ids[1]),
            favorite: true,
        },
    );
    edit(
        &core,
        &rx,
        Command::SetFavorite {
            track: TrackRef::Library(ids[0]),
            favorite: true,
        },
    );
    assert!(core.is_favorite(&TrackRef::Library(ids[0])).unwrap());
    let favorites = core.favorites(0, 10).unwrap();
    assert_eq!(titles(&favorites), ["a", "b"], "the latest first");
    assert!(favorites.iter().all(|r| r.favorite));

    core.send(Command::PlayCollection {
        collection: Collection::Favorites,
        start: 1,
        shuffle: false,
    });
    let events = wait_for(
        &rx,
        Duration::from_secs(20),
        |e| matches!(e, Event::Playback(p) if p.status == Status::Ended),
    );
    assert_eq!(now_playing_titles(&events), vec!["b"]);
    let recent = core.recently_played(10).unwrap();
    assert_eq!(titles(&recent), ["b"], "a finished play counts");
    assert!(recent[0].favorite);
    assert_eq!(titles(&core.most_played(10).unwrap()), ["b"]);

    edit(
        &core,
        &rx,
        Command::SetFavorite {
            track: TrackRef::Library(ids[1]),
            favorite: false,
        },
    );
    assert_eq!(titles(&core.favorites(0, 10).unwrap()), ["a"]);
}

#[test]
fn a_play_skipped_early_does_not_count() {
    let dir = tempfile::tempdir().unwrap();
    let (core, rx, _) = library_core(dir.path(), &[("long.wav", 440.0)], 3.0, true);
    let short = files(dir.path(), &[("short.wav", 550.0)], 0.3).remove(0);
    let ids: Vec<i64> = library_ids(&core).into_iter().map(|(_, id)| id).collect();
    core.send(Command::PlayTracks {
        tracks: vec![TrackRef::Library(ids[0]), TrackRef::File(short.clone())],
        start: 0,
    });
    wait_for(
        &rx,
        Duration::from_secs(10),
        |e| matches!(e, Event::NowPlaying(Some(np)) if np.title == "long"),
    );
    core.send(Command::Next);
    wait_for(
        &rx,
        Duration::from_secs(20),
        |e| matches!(e, Event::Playback(p) if p.status == Status::Ended),
    );
    let recent = core.recently_played(10).unwrap();
    assert_eq!(titles(&recent), ["short"], "only the finished play counts");
    assert_eq!(recent[0].track, TrackRef::File(short));
}

#[test]
fn files_added_to_a_watched_folder_are_scanned() {
    let dir = tempfile::tempdir().unwrap();
    let (core, rx, music) = library_core(dir.path(), &[("first.wav", 440.0)], 0.2, false);
    std::fs::create_dir_all(music.join("New Album")).unwrap();
    files(&music.join("New Album"), &[("second.wav", 550.0)], 0.2);
    let events = wait_for(
        &rx,
        Duration::from_secs(30),
        |e| matches!(e, Event::Scan(ScanStatus::Finished(r)) if r.added > 0),
    );
    let Some(Event::Scan(ScanStatus::Finished(report))) = events.last() else {
        unreachable!()
    };
    assert_eq!(report.added, 1, "{report:?}");
    let names: Vec<String> = library_ids(&core).into_iter().map(|(t, _)| t).collect();
    assert_eq!(names, ["first", "second"]);
}

#[test]
fn crossfade_settings_reach_the_engine() {
    let wav_seconds = |path: &Path| {
        let r = hound::WavReader::open(path).unwrap();
        r.duration() as f64 / f64::from(r.spec().sample_rate)
    };
    for (enabled, expected) in [(false, 4.0), (true, 3.0)] {
        let dir = tempfile::tempdir().unwrap();
        let tracks = files(dir.path(), &[("one.wav", 440.0), ("two.wav", 660.0)], 2.0);
        let out = dir.path().join("out.wav");
        let core = Core::start(config(
            dir.path(),
            OutputKind::WavFile {
                path: out.clone(),
                realtime: false,
            },
            false,
        ))
        .unwrap();
        let rx = core.subscribe();
        core.send(Command::SetCrossfade {
            crossfade: CrossfadeSettings {
                enabled,
                duration_ms: 1_000,
                album_continuity: true,
            },
        });
        core.send(Command::PlayTracks {
            tracks: tracks.into_iter().map(TrackRef::File).collect(),
            start: 0,
        });
        let events = wait_for(
            &rx,
            Duration::from_secs(20),
            |e| matches!(e, Event::Playback(p) if p.status == Status::Ended),
        );
        assert_eq!(now_playing_titles(&events), vec!["one", "two"]);
        assert_eq!(core.snapshot().settings.crossfade.enabled, enabled);
        core.shutdown();
        let seconds = wav_seconds(&out);
        assert!(
            (seconds - expected).abs() < 0.05,
            "crossfade {enabled}: {seconds:.3} s of audio, expected {expected}"
        );
    }
}

#[test]
fn nothing_of_a_song_comes_back_once_the_queue_has_ended() {
    // Short tones rendered as fast as possible: the queue ends (and rewinds to its first song)
    // before the media worker has answered for them. Its late answers must not bring back
    // lyrics or a theme while nothing plays; while a song plays, its own still come.
    for _ in 0..10 {
        let dir = tempfile::tempdir().unwrap();
        let tracks = files(dir.path(), &[("a.wav", 440.0), ("b.wav", 550.0)], 0.1);
        let mut c = config(dir.path(), OutputKind::Null { realtime: false }, false);
        c.watch_folders = false;
        let core = Core::start(c).unwrap();
        let rx = core.subscribe();
        core.send(Command::PlayTracks {
            tracks: tracks.into_iter().map(TrackRef::File).collect(),
            start: 0,
        });
        wait_for(
            &rx,
            Duration::from_secs(20),
            |e| matches!(e, Event::Playback(p) if p.status == Status::Ended),
        );
        // Long enough for the media worker to answer for both songs.
        std::thread::sleep(Duration::from_millis(300));
        let snapshot = core.snapshot();
        assert!(snapshot.now_playing.is_none());
        assert!(snapshot.lyrics.is_none(), "{:?}", snapshot.lyrics);
        assert!(
            snapshot.theme.is_none(),
            "{:?}",
            snapshot.theme.as_ref().map(|t| t.uid)
        );
        core.shutdown();
    }
}

#[test]
fn short_tracks_rendered_offline_are_each_announced_once() {
    // Offline rendering runs far ahead of the actor; the next track must still follow the
    // right one (it once played twice when the list arrived after the engine moved on).
    for _ in 0..15 {
        let dir = tempfile::tempdir().unwrap();
        let tracks = files(
            dir.path(),
            &[("a.wav", 440.0), ("b.wav", 550.0), ("c.wav", 660.0)],
            0.2,
        );
        let mut c = config(dir.path(), OutputKind::Null { realtime: false }, false);
        c.watch_folders = false;
        let core = Core::start(c).unwrap();
        let rx = core.subscribe();
        core.send(Command::PlayTracks {
            tracks: tracks.into_iter().map(TrackRef::File).collect(),
            start: 0,
        });
        let events = wait_for(
            &rx,
            Duration::from_secs(20),
            |e| matches!(e, Event::Playback(p) if p.status == Status::Ended),
        );
        assert_eq!(now_playing_titles(&events), vec!["a", "b", "c"]);
        let plays = core.most_played(10).unwrap();
        assert_eq!(plays.len(), 3, "one counted play each: {plays:?}");
        core.shutdown();
    }
}

#[test]
fn a_fixed_hue_colours_the_theme_with_and_without_a_track() {
    let dir = tempfile::tempdir().unwrap();
    // In real time, so the track's theme arrives while the track still plays.
    let tracks = files(dir.path(), &[("a.wav", 440.0)], 1.0);
    let mut c = config(
        dir.path(),
        OutputKind::WavFile {
            path: dir.path().join("out.wav"),
            realtime: true,
        },
        false,
    );
    c.watch_folders = false;
    let core = Core::start(c).unwrap();
    let rx = core.subscribe();
    let theme_hue = |e: &Event| match e {
        Event::Theme(t) => Some((t.hue, t.uid.is_some())),
        _ => None,
    };

    let mut settings = (*core.snapshot().settings).clone();
    settings.hue_source = HueSource::Fixed { hue: 390.0 };
    core.send(Command::SetSettings {
        settings: settings.clone(),
    });
    let events = wait_for(&rx, Duration::from_secs(10), |e| theme_hue(e).is_some());
    assert_eq!(
        theme_hue(events.last().unwrap()),
        Some((30.0, false)),
        "idle, wrapped to 0..360"
    );
    assert_eq!(core.snapshot().theme.unwrap().hue, 30.0);

    core.send(Command::PlayTracks {
        tracks: tracks.into_iter().map(TrackRef::File).collect(),
        start: 0,
    });
    let events = wait_for(&rx, Duration::from_secs(20), |e| {
        matches!(theme_hue(e), Some((_, true)))
    });
    assert_eq!(
        theme_hue(events.last().unwrap()),
        Some((30.0, true)),
        "the track's theme, fixed hue"
    );

    // The queue may end, and publish the fixed hue's idle theme, before the
    // setting changes: wait for the first theme in another hue, which only the
    // change can publish.
    settings.hue_source = HueSource::Artwork;
    core.send(Command::SetSettings { settings });
    let events = wait_for(
        &rx,
        Duration::from_secs(10),
        |e| matches!(theme_hue(e), Some((hue, _)) if hue != 30.0),
    );
    let (hue, _) = theme_hue(events.last().unwrap()).unwrap();
    assert_eq!(hue, jf_tokens::DEFAULT_HUE, "no artwork: the fallback hue again");
}
